/**
 * Spilled physical result rows keep store-backed terms as dictionary IDs of the evaluation's query source and integer
 * literals as primitive values: replaying a large aggregate output must neither decode every lexical form on the way
 * out nor rebuild simple terms on the way back in.
 */
class NativeResultReplayStoreTermTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(
				new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			conn.begin();
			for (int i = 0; i < 64; i++) {
				conn.add(vf.createIRI(EX, "s" + i), vf.createIRI(EX, "p"), vf.createLiteral("value " + i));
			}
			conn.commit();
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void spilledStoreTermsReplayAsLazyTermsOfTheSameDictionaryId() throws Exception {
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(64L << 10, 64L << 10);
		NativeExecutionContext context = new NativeExecutionContext();
		NativeResultRow.Schema schema = new NativeResultRow.Schema("subject", "count", "foreign");
		try (var dataset = NativeQuerySourceAccess.openExplicitDataset((LmdbStore) repository.getSail());
				var ledger = memory.openQuery();
				context) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			List<Long> subjectIds = new ArrayList<>();
			try (RecordIterator statements = source.statements(NativeLmdbQuerySource.UNKNOWN_ID,
					NativeLmdbQuerySource.UNKNOWN_ID, NativeLmdbQuerySource.UNKNOWN_ID,
					NativeLmdbQuerySource.UNKNOWN_ID)) {
				long[] quad;
				while ((quad = statements.next()) != null) {
					subjectIds.add(quad[0]);
				}
			}
			assertEquals(64, subjectIds.size());
			IRI foreign = SimpleValueFactory.getInstance().createIRI(EX, "not-in-this-store");
			long spilledBytesWithStoreTerms;
			try (NativeResultReplay replay = new NativeResultReplay(schema, context, context.cancellation(), ledger,
					12L << 10).resolvingStoreTermsWith(source)) {
				for (int round = 0; round < 8; round++) {
					for (long id : subjectIds) {
						Value subject = source.lazyValue(id);
						assertInstanceOf(LmdbValue.class, subject);
						replay.append(new NativeResultRow(schema, new NativeResultCell[] {
								NativeResultCell.term(subject),
								NativeResultCell.term(SimpleValueFactory.getInstance()
										.createLiteral(BigInteger.valueOf(1_000_000L + id))),
								NativeResultCell.term(foreign) }));
					}
				}
				replay.finish();
				assertTrue(replay.spilled(), "the fixture must exceed the resident budget");
				spilledBytesWithStoreTerms = replay.spilledBytes();
				try (NativeResultCursor cursor = replay.cursor()) {
					for (int round = 0; round < 8; round++) {
						for (long id : subjectIds) {
							NativeResultRow row = cursor.next();
							Value subject = row.cell("subject").value();
							LmdbValue replayed = assertInstanceOf(LmdbValue.class, subject,
									"a store-backed term replays as a store-backed term, not a rebuilt lexical copy");
							assertEquals(id, replayed.getInternalID());
							assertEquals(source.lazyValue(id), subject);
							Literal count = assertInstanceOf(Literal.class, row.cell("count").value());
							assertEquals(CoreDatatype.XSD.INTEGER, count.getCoreDatatype());
							assertEquals(BigInteger.valueOf(1_000_000L + id), count.integerValue());
							assertEquals(
									SimpleValueFactory.getInstance().createLiteral(BigInteger.valueOf(1_000_000L + id)),
									count);
							assertEquals(foreign, row.cell("foreign").value(),
									"a term outside the source's dictionary keeps the exact lexical spelling");
							assertNotEquals(LmdbValue.class.isInstance(row.cell("foreign").value()), true);
						}
					}
					assertNull(cursor.next());
				}
			}
			// 512 rows: a dictionary ID and a primitive integer each take nine bytes beside the two-byte cell
			// header, so even with the foreign IRI spelled out every row stays well under the lexical encoding.
			long rows = 8L * subjectIds.size();
			assertTrue(spilledBytesWithStoreTerms < rows * 128L,
					() -> "store terms and integer counts must spill compactly: " + spilledBytesWithStoreTerms
							+ " bytes for " + rows + " rows");
			assertEquals(0L, memory.usedBytes());
		}
	}
}
